-- Roughly where the player is inside a dungeon, for the map's "You are here (approx.)" marker (UI/MapHere.lua).
--
-- Inside an instance the client gives an addon no map position (docs/COMPATIBILITY.md section 10), but it names the
-- area the player stands in: GetSubZoneText(), else GetMinimapZoneText(). Data/SubzoneData.lua (generated by
-- tools/gen_subzones.lua) places each named area of a dungeon on its recommended plan's floors. The areas are kept by
-- ID, not by English name, so any client language matches:
--   * an AreaTable area (`a`): its name in the client's language from C_Map.GetAreaInfo(id);
--   * a WMO area (`w`): the client has no call that names it by ID, so the data carries the names the client's own
--     table gives it in each language (`n`), several where rows of the area are spelled differently.
-- A sub-zone that reads the same as the zone (GetZoneText) is the instance itself and places nothing. Every name read
-- from the game passes through Util.Plain; a secret one counts as none.
--
-- Matching is by instance, like Data/Spawns.lua: a player's own plan or a copy of a recommended one gets the same
-- anchors, floor i of the plan being the instance's i-th floor. The player must be inside that instance: the data's
-- instance map ID is GetInstanceInfo's eighth value.

local _, ns = ...
local Subzones = ns:NewModule("Subzones")
local Util = ns.Util

local function call(name, ...)
	local fn = rawget(_G, name)
	if type(fn) ~= "function" then
		return nil
	end
	local ok, value = pcall(fn, ...)
	value = ok and Util.Plain(value) or nil
	return type(value) == "string" and value or nil
end

-- The data of a plan's instance (by its canonical name, else its alias, as Data/Spawns.lua finds spawns), or nil.
function Subzones.For(plan)
	local data = ns.SubzoneData
	local name = type(data) == "table" and type(plan) == "table" and type(plan.instance) == "table"
		and ns.Instances.CanonicalName(plan)
	local key = type(name) == "string" and ns.GameFiles.Key(name)
	if not key then
		return nil
	end
	if data[key] then
		return data[key]
	end
	local spec = ns.GameFiles.INSTANCES and ns.GameFiles.INSTANCES[key]
	local alias = type(spec) == "table" and spec.alias
	return alias and data[alias] or nil
end

-- Where the player is as the client says it: { instanceID, zone, subzone }; subzone nil when there is none, when it
-- reads the same as the zone, or when a value is secret.
function Subzones.Where()
	local info = ns.Instances.Current()
	local zone = call("GetZoneText")
	local sub = call("GetSubZoneText")
	if not sub or sub == "" then
		sub = call("GetMinimapZoneText")
	end
	if sub == "" or sub == zone then
		sub = nil
	end
	return { instanceID = info.inInstance and info.instanceID or nil, zone = zone, subzone = sub }
end

-- The client's language for the data's names: English clients in Britain report enGB.
local function locale()
	local loc = call("GetLocale")
	return (loc == "enGB" or not loc) and "enUS" or loc
end

-- AreaTable names by ID, asked once each (bounded by the areas in the data); false for an ID the client cannot name.
local areaNames = {}

local function areaName(id)
	if areaNames[id] == nil then
		local api = rawget(_G, "C_Map")
		local name
		if type(api) == "table" and type(api.GetAreaInfo) == "function" then
			local ok, value = pcall(api.GetAreaInfo, id)
			value = ok and Util.Plain(value) or nil
			name = type(value) == "string" and value ~= "" and value or nil
		end
		areaNames[id] = name or false
	end
	return areaNames[id] or nil
end

-- Does area `a` of the data read `text` in this client?
function Subzones.Names(a, text)
	if a.a and areaName(a.a) == text then
		return true
	end
	for _, n in ipairs(a.n and a.n[locale()] or {}) do
		if n == text then
			return true
		end
	end
	return false
end

-- The area of `data` (Subzones.For) that `where` (Subzones.Where) names, or nil: only inside that instance.
function Subzones.Find(data, where)
	if type(data) ~= "table" or type(where) ~= "table" or not where.subzone or where.instanceID ~= data.iid then
		return nil
	end
	for _, a in ipairs(data) do
		if Subzones.Names(a, where.subzone) then
			return a
		end
	end
	return nil
end

-- The player's marker on floor `floor` of `plan`: { name = the sub-zone as shown, x, y } in plan space, or nil when
-- the player is not inside its instance, the sub-zone is unknown, or the area has no anchor on that floor. `where`
-- defaults to Subzones.Where().
function Subzones.Here(plan, floor, where)
	where = where or Subzones.Where()
	local a = Subzones.Find(Subzones.For(plan), where)
	if not a then
		return nil
	end
	for _, p in ipairs(a.at) do
		if p[1] == floor then
			return { name = where.subzone, x = p[2], y = p[3] }
		end
	end
	return nil
end

-- Forget the area names asked (tests switch the client's language).
function Subzones.Reset()
	areaNames = {}
end
